        return ClaimView.of(claim, service.roundsBy(sheet, claim), service.logOf(claim.getId()));
    }

    /** A status change the claim's status does not allow, an edit of a claim that is not a DRAFT,
     *  any change to a claim dated in a closed period, a claim dated after its person retired, or a
     *  correction that does not name a SETTLED claim of its person, a move the claim does not allow,
     *  a deferral the claim does not allow, a proof added to a SETTLED or VOID claim, or settling or
     *  approving a claim above the proof threshold with no proofs, or opening a claim above the note
     *  threshold with an empty note, or a split the claim or amount does
     *  not allow, or a void of a SETTLED claim by anyone but a steward or after its void window, or a
     *  void without a reason from the sheet's list while it has one, or a
     *  re-date of a claim that is not OPEN or PENDING, or opening or saving the editor of a claim
     *  another user's editor locks, or a reminder of a claim that is not OPEN or PENDING or was already
     *  reminded on the sheet's today, is refused. */
    @ExceptionHandler({VoidRefusedException.class, StatusChangeRefusedException.class, ClaimNotEditableException.class, CorrectionRefusedException.class,
            PeriodClosedException.class, PersonRetiredException.class, MoveRefusedException.class,
            DeferRefusedException.class, ProofRefusedException.class, ProofRequiredException.class, NoteRequiredException.class,
            SplitRefusedException.class, RedateRefusedException.class, ClaimLockedException.class,
            RemindRefusedException.class, RefInUseException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refused() {
    }

    /** The user who opened a claim cannot settle or approve it, only a steward approves or rejects a
     *  PENDING claim, re-settles a SETTLED one or re-dates a claim, and only a role the sheet's permission matrix allows
     *  opens, settles, voids or moves a claim to another person. */
    @ExceptionHandler({OwnClaimSettleRefusedException.class, ApprovalRefusedException.class, ReassignRefusedException.class,
            ResettleRefusedException.class, PermissionRefusedException.class, RedateForbiddenException.class})
    @ResponseStatus(HttpStatus.FORBIDDEN)
    public void ownClaim() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }

    /** An amount that is not a number or a date that is not a real yyyy-mm-dd date is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}

